-- Backend Engineering ("The Fracture") -- "Deployment, Cloud & Containers" content.
-- Opens Arc VII (Operate). 1 campaign, 2 operations, 12 missions (11 lessons +
-- boss), following the same campaigns -> operations -> missions -> dialogue ->
-- objectives -> challenges -> hints pattern as every prior Act. Uses the
-- slug-based id scheme (world-be-deploy-cloud / mission-be-deploy-cloud-NN).
-- The acts/worlds row for world-be-deploy-cloud already exists (20260810320000);
-- this migration only adds mission content.

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-be-deploy-cloud', 'world-be-deploy-cloud', 'deployment-cloud-and-containers', 'Deployment, Cloud & Containers', 'A routine Friday deploy takes down the whole platform for six minutes -- not an attack, not overload, just stop the old process and start the new one, and hope nothing in between matters. Learn to ship changes without ever betting the whole platform on hope.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-be-deploy-cloud-1', 'campaign-be-deploy-cloud', 'the-machine-underneath', 'The Machine Underneath', 'The Linux runtime, the reverse proxy in front of it, and the containers and pipeline that actually get code onto that runtime -- the floor everything else in this Act stands on.', 1),
  ('operation-be-deploy-cloud-2', 'campaign-be-deploy-cloud', 'shipping-without-a-scar', 'Shipping Without a Scar', 'Rollout strategies that never bet the whole platform on one untested switch, the flags that decouple a release from a deploy, and the cloud building blocks everything above finally runs on.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-be-deploy-cloud-01', 'world-be-deploy-cloud', 'campaign-be-deploy-cloud', 'operation-be-deploy-cloud-1', 'linux-production-runtime', 'Linux Production Runtime', 'The six-minute outage started with a process that just stopped -- and nothing on the box underneath it noticed, restarted it, or told anyone.', 'advanced', ARRAY['mira','forge'], null, null, '{"type":"simulation","simulationId":"linux-production-runtime-sim"}'::jsonb, '{"xp":310,"credits":60}'::jsonb, false, 1),
  ('mission-be-deploy-cloud-02', 'world-be-deploy-cloud', 'campaign-be-deploy-cloud', 'operation-be-deploy-cloud-1', 'reverse-proxy-and-nginx-concepts', 'Reverse Proxy and Nginx Concepts', 'Every request to Forge''s services passes through one thing that decides which box actually answers it -- and for a few minutes last Friday, it kept answering with a box that was already gone.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be-deploy-cloud-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"reverse-proxy-nginx-sim"}'::jsonb, '{"xp":312,"credits":60}'::jsonb, false, 2),
  ('mission-be-deploy-cloud-03', 'world-be-deploy-cloud', 'campaign-be-deploy-cloud', 'operation-be-deploy-cloud-1', 'docker', 'Docker', 'A container is supposed to guarantee: if it built, it runs, anywhere. The box behind last Friday''s outage was running a build nobody else could reproduce.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be-deploy-cloud-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"docker-fundamentals-sim"}'::jsonb, '{"xp":314,"credits":61}'::jsonb, false, 3),
  ('mission-be-deploy-cloud-04', 'world-be-deploy-cloud', 'campaign-be-deploy-cloud', 'operation-be-deploy-cloud-1', 'docker-compose', 'Docker Compose', 'Multiple services, one file, one command to bring them all up together -- and one very easy way to believe a dependency is ready before it actually is.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be-deploy-cloud-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"docker-compose-sim"}'::jsonb, '{"xp":316,"credits":61}'::jsonb, false, 4),
  ('mission-be-deploy-cloud-05', 'world-be-deploy-cloud', 'campaign-be-deploy-cloud', 'operation-be-deploy-cloud-1', 'ci-cd', 'CI/CD', 'A pipeline is supposed to stop broken code before it ships. Last Friday''s build passed a pipeline that never actually checked whether its own tests had passed.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be-deploy-cloud-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"ci-cd-pipeline-sim"}'::jsonb, '{"xp":318,"credits":62}'::jsonb, false, 5),
  ('mission-be-deploy-cloud-06', 'world-be-deploy-cloud', 'campaign-be-deploy-cloud', 'operation-be-deploy-cloud-1', 'environment-promotion', 'Environment Promotion', 'Staging passed everything. Production, on the exact same commit, didn''t -- because production was never actually running the exact same build.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be-deploy-cloud-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"environment-promotion-sim"}'::jsonb, '{"xp":320,"credits":62}'::jsonb, false, 6),
  ('mission-be-deploy-cloud-07', 'world-be-deploy-cloud', 'campaign-be-deploy-cloud', 'operation-be-deploy-cloud-2', 'rolling-deployment', 'Rolling Deployment', 'The missing idea behind Friday''s outage, stated plainly: never take capacity away before its replacement has proven itself.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be-deploy-cloud-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"rolling-deployment-sim"}'::jsonb, '{"xp":322,"credits":62}'::jsonb, false, 7),
  ('mission-be-deploy-cloud-08', 'world-be-deploy-cloud', 'campaign-be-deploy-cloud', 'operation-be-deploy-cloud-2', 'blue-green', 'Blue/Green', 'Sometimes gradual isn''t good enough -- sometimes a release needs to switch all at once, and roll back just as fast if it''s wrong.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be-deploy-cloud-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"blue-green-deployment-sim"}'::jsonb, '{"xp":324,"credits":63}'::jsonb, false, 8),
  ('mission-be-deploy-cloud-09', 'world-be-deploy-cloud', 'campaign-be-deploy-cloud', 'operation-be-deploy-cloud-2', 'canary-deployment', 'Canary Deployment', 'Release to five percent of real traffic first. If it''s going to fail, better it fails for five percent than for everyone.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be-deploy-cloud-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"canary-deployment-sim"}'::jsonb, '{"xp":326,"credits":63}'::jsonb, false, 9),
  ('mission-be-deploy-cloud-10', 'world-be-deploy-cloud', 'campaign-be-deploy-cloud', 'operation-be-deploy-cloud-2', 'feature-flags', 'Feature Flags', 'Shipping the code and turning on the feature don''t have to be the same moment -- and a bad feature can die with a flag flip instead of a rollback.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be-deploy-cloud-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"feature-flags-sim"}'::jsonb, '{"xp":328,"credits":64}'::jsonb, false, 10),
  ('mission-be-deploy-cloud-11', 'world-be-deploy-cloud', 'campaign-be-deploy-cloud', 'operation-be-deploy-cloud-2', 'cloud-backend-building-blocks', 'Cloud Backend Building Blocks', 'Compute, managed databases, object storage, a load balancer that already knows how to health-check -- the building blocks Forge stopped assembling by hand a long time ago.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be-deploy-cloud-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"cloud-building-blocks-sim"}'::jsonb, '{"xp":330,"credits":64}'::jsonb, false, 11),
  ('mission-be-deploy-cloud-12', 'world-be-deploy-cloud', 'campaign-be-deploy-cloud', 'operation-be-deploy-cloud-2', 'deployment-friday', 'Deployment Friday', 'The deploy that took the whole platform down for six minutes, diagnosed end to end -- and one more thing Forge noticed on the way out that nobody asked about yet.', 'boss', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-deploy-cloud-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"deployment-friday-boss-sim"}'::jsonb, '{"xp":680,"credits":158,"badgeIds":["deployment-friday"],"skillXp":{"deployment_and_cloud":30}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-be-deploy-cloud-01', 1, 'mira', 'New Arc. Everything Forge has built now has to actually run somewhere -- not on a laptop, not in a demo, on a real box that has to survive nights nobody is watching it.'),
  ('mission-be-deploy-cloud-01', 2, 'forge', 'Found out exactly how unwatched last Friday. A deploy took the whole platform down for six minutes. Not attacked. Not overloaded. Just... stopped, and nothing running underneath it noticed.'),
  ('mission-be-deploy-cloud-01', 3, 'forge', 'Before we get anywhere near what a good deploy looks like, we need the floor it stands on: what actually keeps a process alive on a Linux server when nobody''s staring at a terminal.'),
  ('mission-be-deploy-cloud-01', 4, 'mira', 'First question, older than any tool in this Act: if a process crashes at 2 a.m., what -- if anything -- is watching, and what does it actually do about it?'),
  ('mission-be-deploy-cloud-02', 1, 'mira', 'Every request to any Forge service crosses one thing before it ever reaches application code: a reverse proxy. It decides which box actually answers, and it can just as easily decide wrong.'),
  ('mission-be-deploy-cloud-02', 2, 'mira', 'Nginx is the specific tool sitting in that seat here. Learn what a server block and a proxy_pass line actually promise, because during the outage, one of them was quietly lying.'),
  ('mission-be-deploy-cloud-03', 1, 'forge', 'A container is supposed to make one promise absolute: if it built here, it runs identically anywhere else. Image once, run everywhere, no surprises.'),
  ('mission-be-deploy-cloud-03', 2, 'forge', 'The box behind Friday''s outage had been running a build nobody else on the team could reproduce. That promise had already been broken before the deploy even started.'),
  ('mission-be-deploy-cloud-04', 1, 'mira', 'One file, multiple services, one command to bring an entire local stack up together. Docker Compose makes that easy -- easy enough to hide a wrong assumption about what "up" actually means.'),
  ('mission-be-deploy-cloud-04', 2, 'mira', 'A container starting is not the same as the service inside it being ready. Confuse those two and you''ll chase a crash loop that isn''t actually random at all.'),
  ('mission-be-deploy-cloud-05', 1, 'forge', 'A pipeline exists to catch broken code before a human ever has to. Build it, test it automatically, and only let what actually passed move forward.'),
  ('mission-be-deploy-cloud-05', 2, 'forge', 'Friday''s build moved forward anyway. Its own test job hadn''t actually passed -- the pipeline just never checked.'),
  ('mission-be-deploy-cloud-06', 1, 'mira', 'Dev, staging, production -- the same code is supposed to move through all three, proven at each stage before the next. The word that matters is "same."'),
  ('mission-be-deploy-cloud-06', 2, 'mira', 'Promote the exact artifact that passed staging. Rebuild it fresh for production, and "passed staging" stops meaning anything at all about what actually ships.'),
  ('mission-be-deploy-cloud-07', 1, 'forge', 'Here''s the idea Friday''s deploy script never had: never remove serving capacity before its replacement has already proven it works.'),
  ('mission-be-deploy-cloud-07', 2, 'forge', 'A rolling deployment brings up the new version, health-checks it, and only then retires an old instance -- one at a time, so there''s never a moment with less healthy capacity than before.'),
  ('mission-be-deploy-cloud-08', 1, 'mira', 'Sometimes gradual isn''t what a release needs. Blue/green keeps two full, identical environments and switches every request from one to the other in a single move.'),
  ('mission-be-deploy-cloud-08', 2, 'mira', 'The upside is speed in both directions: a full release, and a full rollback, both as fast as flipping a router. The cost is running two complete environments at once, even if only for the switch window.'),
  ('mission-be-deploy-cloud-09', 1, 'forge', 'A canary is the middle path: release to a small, real slice of production traffic first, and watch it closely before anyone commits to the rest.'),
  ('mission-be-deploy-cloud-09', 2, 'forge', 'If it''s going to fail under real usage, better it fails for five percent of users for five minutes than for everyone, all at once, with no warning.'),
  ('mission-be-deploy-cloud-10', 1, 'mira', 'A feature flag splits one event into two: deploying code onto production servers, and releasing a feature to actual users. They don''t have to happen at the same time.'),
  ('mission-be-deploy-cloud-10', 2, 'mira', 'Get the flag''s default wrong, though, and it stops gating anything at all -- the code ships silently to everyone the moment it''s deployed, flag or no flag.'),
  ('mission-be-deploy-cloud-11', 1, 'forge', 'Compute, managed databases, object storage, a load balancer that already knows how to health-check -- the pieces every cloud provider sells so nobody has to rack a server by hand anymore.'),
  ('mission-be-deploy-cloud-11', 2, 'forge', 'None of this is new information, exactly. It''s just the first time we''ve named all of it as one set of building blocks instead of six separate problems.'),
  ('mission-be-deploy-cloud-12', 1, 'mira', 'Friday, 4:58 p.m. Someone ran the deploy script the way it''s always been run: stop the old process, start the new one. For six minutes, nothing answered at all.'),
  ('mission-be-deploy-cloud-12', 2, 'forge', 'Every instance went down at once. No health check gated any of it, no old capacity stuck around while the new build proved itself -- there was no rollout strategy here, just an on/off switch.'),
  ('mission-be-deploy-cloud-12', 3, 'mira', 'Walk me through it the way we''ve walked through everything else this Act. What actually happened, and what''s the one change that would have kept this platform answering the whole time?'),
  ('mission-be-deploy-cloud-12', 4, 'forge', '...found it. The deploy script kills every running instance, then starts the replacements -- there''s a window, however short, with zero healthy capacity. A rolling deployment with real health checks never creates that window: it never removes serving capacity until the replacement has already proven itself.'),
  ('mission-be-deploy-cloud-12', 5, 'mira', 'That''s the fix. Stop-then-start assumes the new version is fine before anyone''s checked. It never is, by default -- checking is the whole job.'),
  ('mission-be-deploy-cloud-12', 6, 'forge', '...one more thing, while I had the build pipeline open tracing this. The build-tag template step -- untouched for over a year -- stamps a literal double slash into the tag on every single artifact it''s ever produced. Every deploy we''ve ever shipped carries it.'),
  ('mission-be-deploy-cloud-12', 7, 'mira', 'Noted. File it. It isn''t what took us down Friday, and it isn''t breaking anything today -- but I don''t like how long it''s been sitting there unnoticed. We''re not done asking about that pattern.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-be-deploy-cloud-01-o1', 'mission-be-deploy-cloud-01', 1, 'Own the runtime', 'Decide who -- or what -- should actually be responsible for restarting a crashed production process.'),
  ('mission-be-deploy-cloud-01-o2', 'mission-be-deploy-cloud-01', 2, 'Read the unit file', 'Find the line in a systemd unit file that explains why a crash stayed down until a human noticed.'),
  ('mission-be-deploy-cloud-02-o1', 'mission-be-deploy-cloud-02', 1, 'Name the job', 'Explain what a reverse proxy actually does that justifies putting one in front of every service.'),
  ('mission-be-deploy-cloud-02-o2', 'mission-be-deploy-cloud-02', 2, 'Read the config', 'Find the line sending traffic to a box that no longer exists.'),
  ('mission-be-deploy-cloud-03-o1', 'mission-be-deploy-cloud-03', 1, 'Image vs container', 'Explain the actual difference between a Docker image and a Docker container.'),
  ('mission-be-deploy-cloud-03-o2', 'mission-be-deploy-cloud-03', 2, 'Find the drift', 'Find the line responsible for a build that isn''t actually reproducible.'),
  ('mission-be-deploy-cloud-04-o1', 'mission-be-deploy-cloud-04', 1, 'Trust depends_on correctly', 'Decide what Docker Compose''s depends_on actually guarantees, and what it doesn''t.'),
  ('mission-be-deploy-cloud-04-o2', 'mission-be-deploy-cloud-04', 2, 'Find the crash loop', 'Find the line responsible for the api service starting before its database is actually ready.'),
  ('mission-be-deploy-cloud-05-o1', 'mission-be-deploy-cloud-05', 1, 'Tell CI from CD', 'Match each pipeline behavior to continuous integration, delivery, or deployment.'),
  ('mission-be-deploy-cloud-05-o2', 'mission-be-deploy-cloud-05', 2, 'Find the gap', 'Find the line that let a failing test run reach production anyway.'),
  ('mission-be-deploy-cloud-06-o1', 'mission-be-deploy-cloud-06', 1, 'Promote, don''t rebuild', 'Explain why the same build artifact should move through every environment instead of being rebuilt at each one.'),
  ('mission-be-deploy-cloud-06-o2', 'mission-be-deploy-cloud-06', 2, 'Explain the mismatch', 'Find the evidence that explains a production failure staging never saw, on the exact same commit.'),
  ('mission-be-deploy-cloud-07-o1', 'mission-be-deploy-cloud-07', 1, 'Order the rollout', 'Put the steps of a rolling deployment in the order that actually keeps capacity above zero the whole time.'),
  ('mission-be-deploy-cloud-07-o2', 'mission-be-deploy-cloud-07', 2, 'Name the difference', 'Explain what a rolling deployment does differently from stop-then-start that actually prevents downtime.'),
  ('mission-be-deploy-cloud-08-o1', 'mission-be-deploy-cloud-08', 1, 'Understand the switch', 'Explain what blue/green deployment actually does on release.'),
  ('mission-be-deploy-cloud-08-o2', 'mission-be-deploy-cloud-08', 2, 'Justify the cost', 'Find the evidence that explains why this release needed blue/green instead of a slower rolling deployment.'),
  ('mission-be-deploy-cloud-09-o1', 'mission-be-deploy-cloud-09', 1, 'Name the purpose', 'Explain what a canary release buys you that a full rollout doesn''t.'),
  ('mission-be-deploy-cloud-09-o2', 'mission-be-deploy-cloud-09', 2, 'Read the canary metrics', 'Decide whether the canary''s metrics say proceed or roll back.'),
  ('mission-be-deploy-cloud-10-o1', 'mission-be-deploy-cloud-10', 1, 'Separate deploy from release', 'Explain the actual difference a feature flag creates between deploying code and releasing a feature.'),
  ('mission-be-deploy-cloud-10-o2', 'mission-be-deploy-cloud-10', 2, 'Find the ungated rollout', 'Find the line responsible for a feature reaching everyone instead of only its intended canary group.'),
  ('mission-be-deploy-cloud-11-o1', 'mission-be-deploy-cloud-11', 1, 'Match the building block', 'Match each cloud building block to what it actually provides.'),
  ('mission-be-deploy-cloud-11-o2', 'mission-be-deploy-cloud-11', 2, 'Justify managed services', 'Explain why most teams choose a managed database over running their own.'),
  ('mission-be-deploy-cloud-12-o1', 'mission-be-deploy-cloud-12', 1, 'Diagnose the outage', 'Find the evidence that actually explains the six-minute outage, not just a symptom of it.'),
  ('mission-be-deploy-cloud-12-o2', 'mission-be-deploy-cloud-12', 2, 'Reject the wrong fixes', 'Choose the one fix among plausible alternatives that actually addresses the missing safeguard.'),
  ('mission-be-deploy-cloud-12-o3', 'mission-be-deploy-cloud-12', 3, 'Confirm the fix holds', 'Decide whether a relabeled "rolling deploy" script actually closes the gap that caused the outage.'),
  ('mission-be-deploy-cloud-12-o4', 'mission-be-deploy-cloud-12', 4, 'Close the incident', 'State the actual root cause of Friday''s outage and the fix that would have prevented it.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-be-deploy-cloud-01-o1-c1', 'mission-be-deploy-cloud-01-o1', 1, 'multiple_choice', 'The old deploy process ran the server with a foreground command in an SSH session and disconnected. What''s the fundamental problem with that on production?', '{"question":"The old deploy process runs the server with \"node server.js &\" in a terminal SSH session and disconnects. What''s the fundamental problem with this on production?","options":[{"id":"a","text":"None -- it works as long as nobody closes the laptop"},{"id":"b","text":"The process has no supervisor: nothing restarts it on crash, nothing keeps it alive across a reboot, and closing that SSH session can kill it outright"},{"id":"c","text":"It only matters if the server has multiple CPUs"},{"id":"d","text":"This is a networking problem, not a process problem"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be-deploy-cloud-01-o2-c1', 'mission-be-deploy-cloud-01-o2', 1, 'code_debugging', 'A crash at 2 a.m. left the API down until someone noticed the next morning. Which line in this systemd unit is why it never came back on its own?', '{"language":"bash","code":"[Unit]\nDescription=Forge Dispatch API\nAfter=network.target\n\n[Service]\nExecStart=/usr/bin/node /opt/forge/server.js\nUser=forge-svc\nWorkingDirectory=/opt/forge\nRestart=no\nEnvironment=NODE_ENV=production\n\n[Install]\nWantedBy=multi-user.target","question":"A crash at 2 a.m. left the API down until someone noticed it manually the next morning. Which line in this unit file is why systemd never brought it back up on its own?"}'::jsonb, '{"requiredLineIds":["Restart=no"]}'::jsonb),

  ('mission-be-deploy-cloud-02-o1-c1', 'mission-be-deploy-cloud-02-o1', 1, 'multiple_choice', 'Why put a reverse proxy in front of application servers instead of exposing them directly to the internet?', '{"question":"Why put a reverse proxy in front of application servers instead of exposing them directly to the internet?","options":[{"id":"a","text":"It makes the application code itself run faster"},{"id":"b","text":"It gives you a single, controlled entry point: TLS termination, routing to the right backend by host or path, and hiding internal ports and topology from the internet"},{"id":"c","text":"It replaces the need for a firewall entirely"},{"id":"d","text":"It is a mandatory part of the HTTP/1.1 specification"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be-deploy-cloud-02-o2-c1', 'mission-be-deploy-cloud-02-o2', 1, 'code_debugging', 'This server block defines an upstream with two healthy backends, but requests keep landing on a third box that was decommissioned last week. Which line is actually sending traffic there?', '{"language":"bash","code":"upstream forge_api {\n    server 10.0.4.11:4000;\n    server 10.0.4.12:4000;\n}\n\nserver {\n    listen 443 ssl;\n    server_name api.nexuscity.io;\n\n    location / {\n        proxy_pass http://10.0.4.9:4000;\n        proxy_set_header Host $host;\n    }\n}","question":"This server block defines an upstream with two healthy backends, but requests keep landing on a third box that was decommissioned last week. Which line is actually sending traffic there?"}'::jsonb, '{"requiredLineIds":["        proxy_pass http://10.0.4.9:4000;"]}'::jsonb),

  ('mission-be-deploy-cloud-03-o1-c1', 'mission-be-deploy-cloud-03-o1', 1, 'multiple_choice', 'What''s the actual difference between a Docker image and a Docker container?', '{"question":"What''s the actual difference between a Docker image and a Docker container?","options":[{"id":"a","text":"They''re the same thing, just different names for it"},{"id":"b","text":"An image is the built, immutable template (filesystem plus instructions); a container is a running -- or stopped -- instance of that image, and you can start many containers from one image"},{"id":"c","text":"An image only exists while its container is running"},{"id":"d","text":"A container has to exist before an image can be built"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be-deploy-cloud-03-o2-c1', 'mission-be-deploy-cloud-03-o2', 1, 'code_debugging', 'Two engineers built this image a week apart and got two different sets of dependency versions baked in, even though neither touched package.json. Which line is why the build wasn''t reproducible?', '{"language":"bash","code":"FROM node:20\n\nWORKDIR /app\nCOPY package.json .\nRUN npm install\nCOPY . .\n\nCMD [\"node\", \"server.js\"]","question":"Two engineers built this image a week apart and got two different sets of dependency versions baked in, even though neither touched package.json. Which line is why the build wasn''t reproducible?"}'::jsonb, '{"requiredLineIds":["RUN npm install"]}'::jsonb),

  ('mission-be-deploy-cloud-04-o1-c1', 'mission-be-deploy-cloud-04-o1', 1, 'multiple_choice', 'A compose file declares api as depends_on db. Does that guarantee the database is actually ready to accept connections before api starts?', '{"question":"A compose file declares \"api\" with \"depends_on: [db]\". Does that guarantee the database is actually ready to accept connections before \"api\" starts?","options":[{"id":"a","text":"Yes, that is exactly what depends_on means"},{"id":"b","text":"No -- depends_on only waits for the db container process to start, not for Postgres inside it to finish initializing and accept connections, so api can still crash trying to connect too early"},{"id":"c","text":"Only if both services use the exact same image"},{"id":"d","text":"Docker Compose does not support depends_on"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be-deploy-cloud-04-o2-c1', 'mission-be-deploy-cloud-04-o2', 1, 'code_debugging', 'The api container keeps crash-looping on startup with a database connection error, even though db always starts first. Which line is why api never actually waits for Postgres to be ready?', '{"language":"yaml","code":"services:\n  db:\n    image: postgres:16\n    environment:\n      POSTGRES_PASSWORD: devpass\n\n  api:\n    build: .\n    depends_on:\n      - db\n    ports:\n      - \"4000:4000\"","question":"The api container keeps crash-looping on startup with a database connection error, even though db always starts first. Which line is why api never actually waits for Postgres to be ready?"}'::jsonb, '{"requiredLineIds":["      - db"]}'::jsonb),

  ('mission-be-deploy-cloud-05-o1-c1', 'mission-be-deploy-cloud-05-o1', 1, 'drag_and_drop', 'Match each pipeline behavior to continuous integration, delivery, or deployment.', '{"items":[{"id":"i1","text":"Every push automatically triggers a build and a test run"},{"id":"i2","text":"Every change that passes CI is automatically packaged into a deployable artifact"},{"id":"i3","text":"Every artifact that passes is automatically released to production, with no human in the loop"}],"targets":[{"id":"t1","label":"Continuous Integration"},{"id":"t2","label":"Continuous Delivery"},{"id":"t3","label":"Continuous Deployment"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t3"}}'::jsonb),
  ('mission-be-deploy-cloud-05-o2-c1', 'mission-be-deploy-cloud-05-o2', 1, 'code_debugging', 'The pipeline is wired so deploy only runs after test succeeds -- and broken code still reached production. Which line is why a failing test run didn''t actually stop it?', '{"language":"yaml","code":"jobs:\n  test:\n    steps:\n      - run: npm test\n        continue-on-error: true\n\n  deploy:\n    needs: test\n    steps:\n      - run: npm run build\n      - run: ./deploy.sh production","question":"The pipeline is wired so deploy only runs after test succeeds -- and broken code still reached production. Which line is why a failing test run didn''t actually stop it?"}'::jsonb, '{"requiredLineIds":["        continue-on-error: true"]}'::jsonb),

  ('mission-be-deploy-cloud-06-o1-c1', 'mission-be-deploy-cloud-06-o1', 1, 'multiple_choice', 'Why promote the exact same built artifact from staging to production instead of running a fresh build for each environment?', '{"question":"Why promote the exact same built artifact from staging to production instead of running a fresh build for each environment?","options":[{"id":"a","text":"It is faster to always rebuild from scratch"},{"id":"b","text":"A fresh build per environment risks a different dependency version, a different compiler flag, or a different base image resolving between builds -- so \"it passed staging\" stops actually meaning anything about what ships to production"},{"id":"c","text":"Production always requires a different programming language than staging"},{"id":"d","text":"Rebuilding per environment is never possible in CI"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be-deploy-cloud-06-o2-c1', 'mission-be-deploy-cloud-06-o2', 1, 'investigation', 'Staging passed every check. Production, on the exact same commit, threw an error staging never saw. Which piece of evidence explains how that''s possible?', '{"evidence":[{"id":"ev1","label":"Staging deploy log","detail":"Built commit a3f9c1 at 14:02, deployed the resulting artifact directly"},{"id":"ev2","label":"Production deploy log","detail":"Rebuilt commit a3f9c1 from source at 14:47, deployed that new build"},{"id":"ev3","label":"Dependency lockfile","detail":"Unchanged between 14:02 and 14:47"}],"question":"Staging passed every check. Production, on the exact same commit, threw an error staging never saw. Which piece of evidence explains how that''s possible?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),

  ('mission-be-deploy-cloud-07-o1-c1', 'mission-be-deploy-cloud-07-o1', 1, 'interactive_diagram', 'Order the steps of a rolling deployment so capacity never drops below what it was before the deploy started.', '{"diagramId":"rolling-deployment-sequence","hotspots":[{"id":"deploy_new","label":"Start one new-version instance","explanation":"A single instance running the new code comes up alongside the existing old-version fleet."},{"id":"health_check","label":"New instance passes its health check","explanation":"The instance is confirmed actually able to serve traffic, not just running."},{"id":"shift_traffic","label":"Traffic begins routing to the new instance","explanation":"Only now does the load balancer start sending it real requests."},{"id":"retire_old","label":"One old-version instance is retired","explanation":"Capacity is only removed after its replacement has already proven itself healthy."},{"id":"repeat","label":"Repeat until every instance runs the new version","explanation":"The fleet is replaced gradually, with old and new versions coexisting throughout."}],"task":"Order the steps of a rolling deployment so capacity never drops below what it was before the deploy started."}'::jsonb, '{"correctOrderIds":["deploy_new","health_check","shift_traffic","retire_old","repeat"]}'::jsonb),
  ('mission-be-deploy-cloud-07-o2-c1', 'mission-be-deploy-cloud-07-o2', 1, 'multiple_choice', 'The old deploy process stopped every instance of the old version, then started the new version. What does a rolling deployment do differently that actually prevents downtime?', '{"question":"The old deploy process stopped every instance of the old version, then started the new version. What does a rolling deployment do differently that actually prevents downtime?","options":[{"id":"a","text":"It deploys the new code faster"},{"id":"b","text":"It never removes serving capacity until its replacement has already passed a health check, so there is always at least as much healthy capacity as before, the whole way through"},{"id":"c","text":"It skips the build step entirely"},{"id":"d","text":"It only works with a single server, so there is nothing to coordinate"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be-deploy-cloud-08-o1-c1', 'mission-be-deploy-cloud-08-o1', 1, 'multiple_choice', 'Blue/green deployment keeps two complete, identical production environments (blue = live, green = idle). What actually happens on release?', '{"question":"Blue/green deployment keeps two complete, identical production environments (blue = live, green = idle). What actually happens on release?","options":[{"id":"a","text":"Blue and green each permanently serve half of live traffic"},{"id":"b","text":"The new version is fully deployed to the idle environment, verified, then the router switches all live traffic to it at once -- and rolling back is just switching the router back"},{"id":"c","text":"Blue and green take turns processing requests every other minute"},{"id":"d","text":"There is no idle environment; blue/green is purely a naming convention"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be-deploy-cloud-08-o2-c1', 'mission-be-deploy-cloud-08-o2', 1, 'investigation', 'Which piece of evidence best explains why this team chose blue/green over a slower rolling deployment for this particular release?', '{"evidence":[{"id":"ev1","label":"Rollback requirement","detail":"If the new version has any problem, it must be fully reverted within seconds, not minutes"},{"id":"ev2","label":"Infrastructure budget note","detail":"Running a second full-size production environment roughly doubles compute cost during the switch window"},{"id":"ev3","label":"Team size","detail":"Two backend engineers currently on call"}],"question":"Which piece of evidence best explains why this team chose blue/green over a slower rolling deployment for this particular release?"}'::jsonb, '{"requiredEvidenceIds":["ev1"]}'::jsonb),

  ('mission-be-deploy-cloud-09-o1-c1', 'mission-be-deploy-cloud-09-o1', 1, 'multiple_choice', 'What does a canary deployment actually buy you that a full rolling deploy or blue/green switch doesn''t?', '{"question":"What does a canary deployment actually buy you that a full rolling deploy or blue/green switch doesn''t?","options":[{"id":"a","text":"It is just a faster version of a rolling deployment"},{"id":"b","text":"It exposes the new version to a small, real slice of production traffic first, so a bug that only shows up under real usage is caught while it can still only hurt a small fraction of users, before a full rollout"},{"id":"c","text":"It removes the need for any monitoring"},{"id":"d","text":"It requires no health checks at all"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be-deploy-cloud-09-o2-c1', 'mission-be-deploy-cloud-09-o2', 1, 'investigation', 'Should the canary proceed to a full rollout, or roll back? Which evidence actually decides it?', '{"evidence":[{"id":"ev1","label":"Canary error rate, overall","detail":"New version: 0.4% error rate. Baseline (old version): 0.3% error rate."},{"id":"ev2","label":"Canary error rate, by endpoint","detail":"New version: 6.1% error rate specifically on /dispatch. Baseline: 0.3% on the same endpoint."},{"id":"ev3","label":"Canary latency","detail":"New version p50 is 4ms slower than baseline, within normal noise"}],"question":"Should the canary proceed to a full rollout, or roll back? Which evidence actually decides it?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),

  ('mission-be-deploy-cloud-10-o1-c1', 'mission-be-deploy-cloud-10-o1', 1, 'multiple_choice', 'What''s the actual difference a feature flag creates between "deploying" code and "releasing" a feature?', '{"question":"What''s the actual difference a feature flag creates between \"deploying\" code and \"releasing\" a feature?","options":[{"id":"a","text":"None, they are the same event"},{"id":"b","text":"Deploying puts the new code on production servers; releasing is turning the flag on so users actually experience the new behavior -- with a flag, those can happen at completely different times, and a bad feature can be killed by flipping the flag instead of rolling back a deploy"},{"id":"c","text":"Feature flags require a full redeploy every time they are toggled"},{"id":"d","text":"Feature flags only work for frontend code"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be-deploy-cloud-10-o2-c1', 'mission-be-deploy-cloud-10-o2', 1, 'code_debugging', 'The new routing engine was supposed to only run for a 5% canary group, but it ran for every single request in production. Which line is why the flag never actually gated anything?', '{"language":"typescript","code":"function handleDispatch(req, res) {\n  if (!featureFlags.isEnabled(\"new-routing-engine\", req.user)) {\n    return legacyRoute(req, res);\n  }\n  return newRoutingEngine(req, res);\n}\n\nfeatureFlags.setDefault(\"new-routing-engine\", true);","question":"The new routing engine was supposed to only run for a 5% canary group, but it ran for every single request in production. Which line is why the flag never actually gated anything?"}'::jsonb, '{"requiredLineIds":["featureFlags.setDefault(\"new-routing-engine\", true);"]}'::jsonb),

  ('mission-be-deploy-cloud-11-o1-c1', 'mission-be-deploy-cloud-11-o1', 1, 'drag_and_drop', 'Match each cloud building block to what it actually provides.', '{"items":[{"id":"i1","text":"Compute (VMs, containers, serverless functions)"},{"id":"i2","text":"Managed database (RDS-style)"},{"id":"i3","text":"Object storage (S3-style)"},{"id":"i4","text":"Managed load balancer / DNS"}],"targets":[{"id":"t1","label":"Where your application code actually runs"},{"id":"t2","label":"Durable, queryable structured data, with backups and failover handled for you"},{"id":"t3","label":"Cheap, durable storage for large blobs like files and images, accessed over HTTP"},{"id":"t4","label":"Routes and distributes incoming traffic, and resolves your domain name to it"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t3","i4":"t4"}}'::jsonb),
  ('mission-be-deploy-cloud-11-o2-c1', 'mission-be-deploy-cloud-11-o2', 1, 'multiple_choice', 'Why do most teams choose a managed database over running their own Postgres on a self-managed VM?', '{"question":"Why do most teams choose a managed database over running their own Postgres on a self-managed VM?","options":[{"id":"a","text":"Managed databases are always cheaper in absolute dollar terms"},{"id":"b","text":"A managed service takes on the undifferentiated operational work -- patching, backups, failover, replication -- that provides no unique value to the product, freeing the team to spend that time on what actually differentiates them"},{"id":"c","text":"Self-managed databases cannot use SQL"},{"id":"d","text":"Managed databases require no configuration of any kind"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be-deploy-cloud-12-o1-c1', 'mission-be-deploy-cloud-12-o1', 1, 'investigation', 'Which piece of evidence actually points at the root cause of the six-minute outage, not just a symptom of it?', '{"evidence":[{"id":"ev1","label":"Traffic graph during the outage","detail":"Request volume was flat, well under normal capacity, for the entire six minutes"},{"id":"ev2","label":"Deploy script","detail":"kill $(pgrep -f server.js); sleep 2; node server.js & -- runs on every instance simultaneously"},{"id":"ev3","label":"Database connection pool metrics","detail":"Idle the entire window, no errors, no saturation"}],"question":"Which piece of evidence actually points at the root cause of the six-minute outage, not just a symptom of it?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),
  ('mission-be-deploy-cloud-12-o2-c1', 'mission-be-deploy-cloud-12-o2', 1, 'multiple_choice', 'Several fixes were on the table before the real one. Which fix actually addresses the missing safeguard, and not just a plausible-sounding workaround?', '{"question":"Several fixes were on the table before the real one. Which fix actually addresses the missing safeguard, and not just a plausible-sounding workaround?","options":[{"id":"a","text":"Buy bigger production servers so restarts finish faster"},{"id":"b","text":"Require a second engineer to approve every deploy by reading the diff"},{"id":"c","text":"Deploy less often, e.g. once a week instead of on demand"},{"id":"d","text":"Replace the deploy script with a rolling deployment that only retires an old instance after its replacement passes a health check, so serving capacity never hits zero"}]}'::jsonb, '{"correctOptionId":"d"}'::jsonb),
  ('mission-be-deploy-cloud-12-o3-c1', 'mission-be-deploy-cloud-12-o3', 1, 'code_debugging', 'This script was relabeled a "rolling deploy," one instance at a time -- but the outage risk is still there. Which line is why?', '{"language":"bash","code":"for instance in $INSTANCES; do\n  start_new_instance \"$instance\"\n  stop_old_instance \"$instance\"\ndone","question":"This script was relabeled a \"rolling deploy,\" one instance at a time -- but the outage risk is still there. Which line is why?"}'::jsonb, '{"requiredLineIds":["  stop_old_instance \"$instance\""]}'::jsonb),
  ('mission-be-deploy-cloud-12-o4-c1', 'mission-be-deploy-cloud-12-o4', 1, 'boss_encounter', 'Synthesize the Friday outage: state the actual root cause and the fix that would have prevented it, not any of the tempting workarounds.', '{"stages":[{"objectiveRef":"mission-be-deploy-cloud-12-o1","label":"Diagnose the outage"},{"objectiveRef":"mission-be-deploy-cloud-12-o2","label":"Reject the wrong fixes"},{"objectiveRef":"mission-be-deploy-cloud-12-o3","label":"Confirm the fix holds"}],"task":"Synthesize the Friday outage: the deploy script killed every instance before starting its replacements, with no health check gating the switch -- that stop-then-start window, not traffic or the database, is the root cause. The fix is a rolling deployment that only retires an old instance once its replacement has already passed a health check, so serving capacity never drops to zero."}'::jsonb, '{"requiredObjectiveIds":["mission-be-deploy-cloud-12-o1","mission-be-deploy-cloud-12-o2","mission-be-deploy-cloud-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-be-deploy-cloud-01-o1-c1', 'orientation', 'Ask what happens the moment that SSH session actually closes.', 10, 1),
  ('mission-be-deploy-cloud-01-o1-c1', 'solution', 'Nothing supervises it: no automatic restart on crash, no survival across a reboot, and the process can die the instant the shell that spawned it goes away.', 20, 2),
  ('mission-be-deploy-cloud-01-o2-c1', 'orientation', 'A crash that stays down is a restart policy problem, not a permissions problem.', 10, 1),
  ('mission-be-deploy-cloud-01-o2-c1', 'concept', 'systemd will only bring a failed service back automatically if its Restart directive tells it to -- otherwise a crash just leaves it stopped.', 20, 2),
  ('mission-be-deploy-cloud-01-o2-c1', 'solution', 'Restart=no explicitly tells systemd not to restart this service on failure -- that is why it stayed down until a human noticed.', 30, 3),

  ('mission-be-deploy-cloud-02-o1-c1', 'orientation', 'Think about what would be exposed to the raw internet if every app server answered requests directly.', 10, 1),
  ('mission-be-deploy-cloud-02-o1-c1', 'solution', 'A reverse proxy is the single controlled front door: it terminates TLS, routes by host or path, and hides internal ports and topology from anyone outside.', 20, 2),
  ('mission-be-deploy-cloud-02-o2-c1', 'orientation', 'The upstream block lists the healthy backends -- but nothing forces every location to actually use it.', 10, 1),
  ('mission-be-deploy-cloud-02-o2-c1', 'concept', 'A proxy_pass line that hardcodes an IP address bypasses the upstream group entirely, healthy or not.', 20, 2),
  ('mission-be-deploy-cloud-02-o2-c1', 'solution', 'proxy_pass http://10.0.4.9:4000; sends every request straight to the decommissioned box, ignoring the upstream forge_api group above it.', 30, 3),

  ('mission-be-deploy-cloud-03-o1-c1', 'orientation', 'One of these is a template. The other is what you get when you actually run that template.', 10, 1),
  ('mission-be-deploy-cloud-03-o1-c1', 'solution', 'An image is the immutable built template; a container is a running instance of it, and one image can produce many containers.', 20, 2),
  ('mission-be-deploy-cloud-03-o2-c1', 'orientation', 'Nothing in this Dockerfile pins dependency versions to an exact, repeatable set.', 10, 1),
  ('mission-be-deploy-cloud-03-o2-c1', 'concept', 'Without a committed lockfile being copied in and installed from, npm install re-resolves version ranges from package.json fresh every time -- and those ranges can resolve differently on different days.', 20, 2),
  ('mission-be-deploy-cloud-03-o2-c1', 'solution', 'RUN npm install is the line: with no lockfile in play, it can install a different exact dependency tree on every build, even with an unchanged package.json.', 30, 3),

  ('mission-be-deploy-cloud-04-o1-c1', 'orientation', 'depends_on is about container start order, not about what is happening inside the container.', 10, 1),
  ('mission-be-deploy-cloud-04-o1-c1', 'solution', 'It only guarantees db''s process starts first -- not that Postgres has finished initializing and is ready to accept connections.', 20, 2),
  ('mission-be-deploy-cloud-04-o2-c1', 'orientation', 'The db service starting is not the same event as Postgres being ready to accept connections.', 10, 1),
  ('mission-be-deploy-cloud-04-o2-c1', 'concept', 'A bare depends_on entry with no health condition just waits for the container process to exist, which is why api can still race ahead of a database that has not finished booting.', 20, 2),
  ('mission-be-deploy-cloud-04-o2-c1', 'solution', 'The plain "- db" entry under depends_on is the gap -- it needs a condition like service_healthy, backed by an actual healthcheck on db, to actually wait for readiness.', 30, 3),

  ('mission-be-deploy-cloud-05-o1-c1', 'orientation', 'One of these three statements has no human decision anywhere in it -- that is the giveaway for which stage it describes.', 10, 1),
  ('mission-be-deploy-cloud-05-o1-c1', 'solution', 'Build-and-test-on-every-push is Continuous Integration; auto-packaging a deployable artifact after CI passes is Continuous Delivery; auto-releasing that artifact with no human gate is Continuous Deployment.', 20, 2),
  ('mission-be-deploy-cloud-05-o2-c1', 'orientation', 'The deploy job is correctly gated on test passing -- so look at what happens inside the test job itself.', 10, 1),
  ('mission-be-deploy-cloud-05-o2-c1', 'concept', 'continue-on-error tells the pipeline to report a step as passed regardless of its actual exit code, which is exactly what lets a real test failure look like a green light downstream.', 20, 2),
  ('mission-be-deploy-cloud-05-o2-c1', 'solution', 'continue-on-error: true on the test step is the gap -- it masks a genuine test failure, so needs: test downstream never actually sees a failure to block on.', 30, 3),

  ('mission-be-deploy-cloud-06-o1-c1', 'orientation', 'Ask what could differ between two builds of the exact same commit run at two different times.', 10, 1),
  ('mission-be-deploy-cloud-06-o1-c1', 'solution', 'Rebuilding per environment risks a different resolved dependency, compiler version, or base image tag between builds -- promoting one artifact keeps what passed staging identical to what reaches production.', 20, 2),
  ('mission-be-deploy-cloud-06-o2-c1', 'orientation', 'The commit is identical in both logs. Something else about the two deploys is not.', 10, 1),
  ('mission-be-deploy-cloud-06-o2-c1', 'solution', 'ev2 -- production rebuilt the commit independently 45 minutes later instead of promoting the already-built and staging-verified artifact, so it was never guaranteed to be byte-for-byte the same build.', 20, 2),

  ('mission-be-deploy-cloud-07-o1-c1', 'orientation', 'Nothing should receive real traffic before it has been confirmed healthy, and nothing old should retire before its replacement has taken over.', 10, 1),
  ('mission-be-deploy-cloud-07-o1-c1', 'solution', 'Start the new instance, health-check it, shift traffic to it, then retire an old instance -- repeat until the whole fleet is replaced.', 20, 2),
  ('mission-be-deploy-cloud-07-o2-c1', 'orientation', 'Ask how much healthy capacity exists at the single worst moment during each strategy.', 10, 1),
  ('mission-be-deploy-cloud-07-o2-c1', 'solution', 'Stop-then-start has a moment with zero healthy capacity by design. A rolling deployment never removes capacity until a health-checked replacement is already serving.', 20, 2),

  ('mission-be-deploy-cloud-08-o1-c1', 'orientation', 'Blue/green is not gradual -- the whole point is that the cutover happens in one move.', 10, 1),
  ('mission-be-deploy-cloud-08-o1-c1', 'solution', 'The idle environment gets the new version fully deployed and verified first, then the router switches all traffic to it at once -- rollback is switching the router back.', 20, 2),
  ('mission-be-deploy-cloud-08-o2-c1', 'orientation', 'Two of these three facts are just costs or context. One is a hard requirement that only an instant, all-at-once switch actually satisfies.', 10, 1),
  ('mission-be-deploy-cloud-08-o2-c1', 'solution', 'ev1 -- a rollback that must complete in seconds, not minutes, is exactly what blue/green''s instant router flip provides that a gradual rolling deploy cannot.', 20, 2),

  ('mission-be-deploy-cloud-09-o1-c1', 'orientation', 'A canary is not about speed -- it is about limiting the blast radius of a mistake.', 10, 1),
  ('mission-be-deploy-cloud-09-o1-c1', 'solution', 'It exposes real production traffic to the new version in a small slice first, so a bug only visible under real usage hurts a few users instead of everyone.', 20, 2),
  ('mission-be-deploy-cloud-09-o2-c1', 'orientation', 'An overall error rate can hide a spike that is concentrated on one specific endpoint.', 10, 1),
  ('mission-be-deploy-cloud-09-o2-c1', 'solution', 'ev2 -- a 6.1% error rate on /dispatch specifically, against a 0.3% baseline, is a real regression the overall number was diluting. Roll back.', 20, 2),

  ('mission-be-deploy-cloud-10-o1-c1', 'orientation', 'A flag adds a second event to what used to be a single moment.', 10, 1),
  ('mission-be-deploy-cloud-10-o1-c1', 'solution', 'Deploying puts code on servers; releasing is turning the flag on for users. Separating them means a bad feature dies with a flag flip, not a rollback.', 20, 2),
  ('mission-be-deploy-cloud-10-o2-c1', 'orientation', 'The per-request check itself looks correct -- ask what value it is actually checking against by default.', 10, 1),
  ('mission-be-deploy-cloud-10-o2-c1', 'concept', 'setDefault controls what the flag evaluates to when nothing more specific overrides it -- setting that default true turns the flag on for every request unless something else narrows it back down.', 20, 2),
  ('mission-be-deploy-cloud-10-o2-c1', 'solution', 'featureFlags.setDefault("new-routing-engine", true); is the line -- it defaults the flag on for everyone, overriding the intended 5% canary targeting.', 30, 3),

  ('mission-be-deploy-cloud-11-o1-c1', 'orientation', 'One of these is where code runs. One stores structured rows. One stores raw blobs. One directs traffic to all of them.', 10, 1),
  ('mission-be-deploy-cloud-11-o1-c1', 'solution', 'Compute runs your code, a managed database holds structured data with backups and failover handled, object storage holds large blobs over HTTP, and a managed load balancer/DNS routes and resolves traffic to it all.', 20, 2),
  ('mission-be-deploy-cloud-11-o2-c1', 'orientation', 'Patching, backups and failover are real, ongoing work -- ask whose time that work is actually worth spending.', 10, 1),
  ('mission-be-deploy-cloud-11-o2-c1', 'solution', 'A managed database absorbs undifferentiated operational work that adds no unique value to the product, freeing the team to spend that time on what actually does.', 20, 2),

  ('mission-be-deploy-cloud-12-o1-c1', 'orientation', 'Rule out anything that is flat or idle during the incident window -- that is not where the cause lives.', 10, 1),
  ('mission-be-deploy-cloud-12-o1-c1', 'solution', 'ev2 -- the deploy script kills every instance and starts replacements simultaneously with no health gate, which is exactly the six-minute window with zero healthy capacity.', 20, 2),
  ('mission-be-deploy-cloud-12-o2-c1', 'orientation', 'Three of these four options never touch the actual moment capacity hits zero.', 10, 1),
  ('mission-be-deploy-cloud-12-o2-c1', 'concept', 'Bigger servers, a second reviewer, and a slower cadence all leave the stop-then-start window fully intact -- none of them add a health check gate.', 20, 2),
  ('mission-be-deploy-cloud-12-o2-c1', 'solution', 'd -- only a rolling deployment gated on health checks ensures serving capacity never drops to zero during a deploy.', 30, 3),
  ('mission-be-deploy-cloud-12-o3-c1', 'orientation', 'Ask what, if anything, happens between starting the new instance and stopping the old one.', 10, 1),
  ('mission-be-deploy-cloud-12-o3-c1', 'concept', 'One instance at a time is progress, but without a health check gating the handoff, the old instance can still be stopped before its replacement is actually verified ready.', 20, 2),
  ('mission-be-deploy-cloud-12-o3-c1', 'solution', 'stop_old_instance "$instance" still runs immediately after starting the new one, with no health check in between -- the zero-capacity risk is still there, just smaller in scope.', 30, 3),
  ('mission-be-deploy-cloud-12-o4-c1', 'orientation', 'Look at what all three findings pointed at as one root cause, not three separate problems.', 15, 1),
  ('mission-be-deploy-cloud-12-o4-c1', 'solution', 'The outage was a stop-then-start deploy with no health check gating the handoff, not traffic or the database. The fix is a rolling deployment: never retire an old instance until its replacement has already passed a health check.', 25, 2);
